const BASELINE = Buffer.from(
    "",
    "base64"
);

const PROGRESSIVE = Buffer.from(
    "",
    "base64"
);

const ICC_PROFILE = Buffer.from(
    "",
    "base64"
);


function appSegment(marker, payload) {

    if (payload.length > 65533) {
        throw new Error("JPEG test segment is too large");
    }

    const header = Buffer.alloc(4);

    header[0] = 0xff;
    header[1] = marker;
    header.writeUInt16BE(payload.length + 2, 2);
    return Buffer.concat([header, payload]);

}


function addSegment(jpeg, marker, payload) {

    return Buffer.concat([
        jpeg.subarray(0, 2),
        appSegment(marker, payload),
        jpeg.subarray(2)
    ]);

}


function exifJpeg(withThumbnail) {

    const thumbnail = withThumbnail
        ? BASELINE
        : Buffer.alloc(0);

    const tiffLength = withThumbnail
        ? 56 + thumbnail.length
        : 26;

    const tiff = Buffer.alloc(tiffLength);

    tiff.write("II", 0, "ascii");
    tiff.writeUInt16LE(42, 2);
    tiff.writeUInt32LE(8, 4);
    tiff.writeUInt16LE(1, 8);
    tiff.writeUInt16LE(0x0112, 10);
    tiff.writeUInt16LE(3, 12);
    tiff.writeUInt32LE(1, 14);
    tiff.writeUInt16LE(6, 18);
    tiff.writeUInt32LE(withThumbnail ? 26 : 0, 22);

    if (withThumbnail) {
        tiff.writeUInt16LE(2, 26);
        tiff.writeUInt16LE(0x0201, 28);
        tiff.writeUInt16LE(4, 30);
        tiff.writeUInt32LE(1, 32);
        tiff.writeUInt32LE(56, 36);
        tiff.writeUInt16LE(0x0202, 40);
        tiff.writeUInt16LE(4, 42);
        tiff.writeUInt32LE(1, 44);
        tiff.writeUInt32LE(thumbnail.length, 48);
        tiff.writeUInt32LE(0, 52);
        thumbnail.copy(tiff, 56);
    }

    return addSegment(
        BASELINE,
        0xe1,
        Buffer.concat([
            Buffer.from("Exif\0\0", "binary"),
            tiff
        ])
    );

}


module.exports = {
    baseline: BASELINE,
    exifOrientation: exifJpeg(false),
    exifThumbnail: exifJpeg(true),
    iccProfile: ICC_PROFILE,
    progressive: PROGRESSIVE
};
